//! CASSCF and MC-PDFT energies against frozen external oracle values
//! (`tests/oracle_data/mcpdft_oracle.json`, generated by
//! `tools/oracle/gen_mcpdft.py`): full-valence water CAS(8,6) with the
//! translated, fully translated and hybrid PBE on-top functionals; lithium
//! hydride CAS(2,2) with two averaged states in the state-specific,
//! compressed, linearized and extended multistate forms; and H2 CAS(2,2).
//! The oracle converged its orbital gradient to 1e-6 and integrated on its
//! own finest grid, so the PDFT energies, which follow the orbitals
//! linearly, are compared at 2e-5 Hartree; the active-space energies are
//! stationary in the orbitals and are compared at 1e-6 Hartree.
//!
//! The first run with integration level 6 failed the LiH L-PDFT bound:
//! errors [3.390e-5, -4.600e-5] Hartree. Levels 6, 7, 8, 9 give maximum
//! errors 4.600e-5, 8.279e-6, 4.058e-5, 3.091e-6 at the same orbitals.
//! Tightening the orbital gradient from 1e-8 to 1e-12 changes these errors
//! by less than 7e-11 Hartree. The translated potential is nonsmooth at
//! R = 1, so convergence of its quadrature need not be monotone. Use level
//! 9 for the oracle comparison; retain both original energy bounds.

use dft_rs::driver::{run, Controls, System, Value};

fn system(name: &str) -> System {
    match name {
        "water" => System::molecule(
            vec![8, 1, 1],
            vec![
                [0.0, 0.0, 0.23],
                [0.0, 1.4309, -0.8867],
                [0.12, -1.4809, -0.9067],
            ],
        ),
        "lithium hydride" => System::molecule(vec![3, 1], vec![[0.0; 3], [0.0, 0.0, 3.015]]),
        "hydrogen" => System::molecule(vec![1, 1], vec![[0.0; 3], [0.0, 0.0, 1.4]]),
        other => panic!("unknown oracle molecule {other}"),
    }
}

fn floats(v: &Value, key: &str) -> Vec<f64> {
    v.get(key).unwrap().numeric_array().unwrap().1
}

#[test]
fn energies_match_the_frozen_oracle() {
    let data = Value::parse_json(include_str!("oracle_data/mcpdft_oracle.json")).unwrap();
    let cases = data.get("cases").and_then(Value::as_array).unwrap();
    assert!(cases.len() >= 9);
    for case in cases {
        let text = |key: &str| case.get(key).and_then(Value::as_str).unwrap().to_string();
        let cas = floats(case, "cas");
        let roots = case.get("roots").and_then(Value::as_i64).unwrap();
        let controls = Controls::from_value(&Value::Object(vec![
            ("basis".into(), Value::Str("sto-3g".into())),
            ("xc".into(), Value::Str("hf".into())),
            ("conv_tol".into(), Value::Float(1e-12)),
            ("grid_level".into(), Value::Int(9)),
            ("casscf_gradient_tol".into(), Value::Float(1e-10)),
            ("ci_tol".into(), Value::Float(1e-12)),
            (
                "cas".into(),
                Value::Array(cas.iter().map(|v| Value::Int(*v as i64)).collect()),
            ),
            ("cas_roots".into(), Value::Int(roots)),
            (
                "on_top_functional".into(),
                Value::Str(text("on_top_functional")),
            ),
            ("pdft_method".into(), Value::Str(text("method"))),
        ]))
        .unwrap();
        let report = run("mcpdft", &system(&text("molecule")), &controls).unwrap();
        let defect = |key: &str| -> f64 {
            let actual = floats(&report, key);
            let expected = floats(case, key);
            assert_eq!(actual.len(), expected.len(), "{key}");
            actual
                .iter()
                .zip(expected)
                .fold(0.0_f64, |m, (a, b)| m.max((a - b).abs()))
        };
        let (reference, pdft) = (defect("cas_energies"), defect("pdft_energies"));
        println!(
            "{} {} {}: active-space {reference:.3e}, PDFT {pdft:.3e}",
            text("molecule"),
            text("on_top_functional"),
            text("method")
        );
        assert!(reference < 1e-6);
        assert!(pdft < 2e-5);
        if let Some(terms) = case.get("state_terms") {
            for key in [
                "state_nuclear_repulsion",
                "state_one_electron",
                "state_coulomb",
                "state_on_top",
            ] {
                let actual = floats(&report, key);
                let expected = floats(terms, key);
                assert_eq!(actual.len(), expected.len(), "{key}");
                let error = actual
                    .iter()
                    .zip(&expected)
                    .fold(0.0_f64, |m, (a, b)| m.max((a - b).abs()));
                println!("  {key}: actual {actual:?} oracle {expected:?} error {error:.12e}");
                let bound = if key == "state_nuclear_repulsion" {
                    1e-11
                } else {
                    2e-5
                };
                assert!(error < bound, "{key}: {error:.12e}");
            }
        }
    }
}
